const WEBHOOK_SHARED_TOKEN = 'change-me-before-demo';
const request = $json;
const body = request.body ?? request;
const headers = request.headers ?? {};

function headerValue(name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) {
      return Array.isArray(value) ? value[0] : value;
    }
  }
  return undefined;
}

function normalizeString(value, maxLength = 128) {
  if (value === undefined || value === null) {
    return null;
  }
  return String(value).slice(0, maxLength);
}

function boundedNumber(value, max = 10000) {
  const number = Number(value);
  if (!Number.isFinite(number) || number < 0) {
    return 0;
  }
  return Math.min(number, max);
}

function safeEqual(a, b) {
  const left = String(a ?? '');
  const right = String(b ?? '');
  if (left.length !== right.length) {
    return false;
  }
  let diff = 0;
  for (let index = 0; index < left.length; index += 1) {
    diff |= left.charCodeAt(index) ^ right.charCodeAt(index);
  }
  return diff === 0;
}

const providedToken = normalizeString(headerValue('x-video-security-token'), 256);
if (!safeEqual(providedToken, WEBHOOK_SHARED_TOKEN)) {
  return [{
    json: {
      receivedAt: new Date().toISOString(),
      security: {
        authorized: false,
        reason: 'Invalid or missing X-Video-Security-Token header'
      },
      source: normalizeString(body.source ?? 'unknown'),
      eventType: normalizeString(body.eventType ?? 'unknown'),
      risk: {
        severity: 'critical',
        score: 0,
        reasons: ['Webhook authentication failed'],
        action: 'reject: invalid webhook token'
      }
    }
  }];
}

const allowedSeverities = new Set(['critical', 'high', 'medium', 'low', 'informational']);
const severityWeight = { critical: 90, high: 70, medium: 45, low: 20, informational: 5 };
const rawSeverity = String(body.severity ?? 'informational').toLowerCase();
const severity = allowedSeverities.has(rawSeverity) ? rawSeverity : 'informational';
const rawSignals = body.signals ?? {};
const event = {
  source: normalizeString(body.source ?? 'unknown'),
  eventType: normalizeString(body.eventType ?? 'unknown'),
  roomId: normalizeString(body.roomId),
  participantId: normalizeString(body.participantId),
  timestamp: normalizeString(body.timestamp, 64),
  evidence: {
    zapReport: normalizeString(body.evidence?.zapReport, 256),
    strideReport: normalizeString(body.evidence?.strideReport, 256)
  },
  signals: {
    iceFailed: boundedNumber(rawSignals.iceFailed),
    dtlsFailed: boundedNumber(rawSignals.dtlsFailed),
    producerCount: boundedNumber(rawSignals.producerCount),
    consumerCount: boundedNumber(rawSignals.consumerCount),
    zapAlerts: boundedNumber(rawSignals.zapAlerts),
    publicIpCandidateObserved: rawSignals.publicIpCandidateObserved === true,
    unauthorizedJoinAttempts: boundedNumber(rawSignals.unauthorizedJoinAttempts)
  }
};

let score = severityWeight[severity] ?? 5;
const reasons = [];
function add(condition, points, reason) {
  if (condition) {
    score += points;
    reasons.push(reason);
  }
}

const timestampMs = Date.parse(event.timestamp ?? '');
add(event.timestamp !== null && Number.isNaN(timestampMs), 5, 'Invalid event timestamp');
add(Number.isFinite(timestampMs) && Math.abs(Date.now() - timestampMs) > 10 * 60 * 1000, 5, 'Event timestamp is outside the 10 minute freshness window');
add(event.signals.iceFailed >= 3, 10, 'ICE failure spike');
add(event.signals.dtlsFailed >= 1, 10, 'DTLS failure observed');
add(event.signals.producerCount >= 10, 8, 'Unexpected producer count');
add(event.signals.consumerCount >= 80, 8, 'Unexpected consumer fanout');
add(event.signals.zapAlerts >= 4, 6, 'ZAP alerts present');
add(event.signals.publicIpCandidateObserved === true, 8, 'Public IP candidate observed');
add(event.signals.unauthorizedJoinAttempts >= 2, 10, 'Repeated unauthorized join attempts');

score = Math.min(score, 100);
const action = score >= 80
  ? 'contain: lock room, require moderator review, preserve evidence, notify security owner'
  : score >= 60
    ? 'investigate: notify moderator and create follow-up ticket'
    : 'monitor: keep event in audit log';

return [{
  json: {
    receivedAt: new Date().toISOString(),
    security: {
      authorized: true,
      tokenChecked: true
    },
    event,
    risk: {
      severity,
      score,
      reasons,
      action
    }
  }
}];
